{
  "status": "SUPPORTED",
  "task_summary": "Arrange refreshment settings for two people near their seats and position a remote control for shared access.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "person",
        "entity_kind": "REGION",
        "function": "Reference point for placing refreshments and control",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["human", "viewer", "guest"],
        "required_properties": []
      },
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Holds drink and food for consumption",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate", "bowl", "napkin_set"],
        "required_properties": ["holds_liquid", "holds_food"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operates the television",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["remote", "controller", "mouse"],
        "required_properties": ["buttons", "wireless"]
      },
      {
        "id": "support_surface",
        "entity_kind": "OBJECT",
        "function": "Supports refreshment settings and control",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "side_table", "coffee_table", "console_table"],
        "required_properties": ["flat", "stable"]
      },
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "Displays content for viewing",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["tv", "screen", "monitor"],
        "required_properties": ["displays_video"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_proximity",
        "relation": "is_near",
        "participant_roles": ["person", "refreshment_setting"],
        "required": true
      },
      {
        "id": "setting_support",
        "relation": "is_on",
        "participant_roles": ["refreshment_setting", "support_surface"],
        "required": true
      },
      {
        "id": "control_access",
        "relation": "is_accessible_to",
        "participant_roles": ["entertainment_control", "person"],
        "required": true
      },
      {
        "id": "viewing_arrangement",
        "relation": "faces",
        "participant_roles": ["person", "television"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "set_refreshments",
        "operation": "place_on_surface",
        "participant_roles": ["refreshment_setting", "support_surface", "person"],
        "operation_count": 2
      },
      {
        "id": "position_control",
        "operation": "move_to_accessible_spot",
        "participant_roles": ["entertainment_control", "support_surface", "person"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "person": [],
