      ],
      "support_surface": [
        {"label": "coffee_table", "visual_description": "Large wooden table in center"},
        {"label": "side_table_1", "visual_description": "Small wooden table next to left chair"},
        {"label": "side_table_2", "visual_description": "Small wooden table next to right chair"},
        {"label": "console_table", "visual_description": "Long wooden table under TV"}
      ],
      "television": [
        {"label": "wall_mounted_tv", "visual_description": "Black screen on wall"}
      ]
    },
    "inspectable_regions": [
      {
        "id": "coffee_table",
