        "reason": "Contains all current refreshment items and remote; likely source for redistribution."
      },
      {
        "id": "side_table_1",
        "label": "Left Side Table",
        "visual_description": "Empty shelf next to chair",
        "reason": "Suitable surface for placing one refreshment setting near a person."
      },
      {
        "id": "side_table_2",
        "label": "Right Side Table",
