        "reason": "Suitable surface for placing one refreshment setting near a person."
      },
      {
        "id": "console_table",
        "label": "Console Table",
        "visual_description": "Table under TV with items",
        "reason": "Central location potentially ideal for accessible entertainment control."
      }
